quests[43685] = { id = 43685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylactery Used" }
quests[43686] = { id = 43686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fourth Horseman", description = "The Lich King demands too much! Tirion Fordring deserves more than a life of anguish and undeath!\n\nKnow this, Deathlord... I will obey your will, but there will be no redemption for what we are about to do.\n\nThe Silver Hand will never hand Tirion to us. The path to the Fourth Horseman will be soaked in righteous blood!\n\nBlood that will stain our hands forever.\n\nYour will be done, Deathlord. I will begin the preparations to invade Light's Hope. If this is what it takes to save our world, so be it!", completion = "I see now what I did not see before. My destiny was written long ago.\n\nThis burden has always been mine to bear.", objectives = "Obtain the Fourth Horseman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43687] = { id = 43687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking in Shadows", description = "If we are to infuse the shard's power into the Ashbringer we will need help. We cannot wield such dark magic; however, I know who can...\n\nThe Knights of the Ebon Blade.\n\nI will commission a flight for you to Acherus at once and meet you there - find Aludane Whitecloud in Dalaran when you are ready.", progress = "Darion owes us this much after all his kind have done.", completion = "It is done. I hope you're right about this, Highlord.", objectives = "Seek the aid of the Knights of the Ebon Blade in Acherus above the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43688] = { id = 43688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shard Delivered" }
