quests[43695] = { id = 43695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Pair of Goggles" }
quests[43696] = { id = 43696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Lumenstone 1" }
quests[43697] = { id = 43697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warriors of Light", description = "We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.", progress = "We rejoice in our triumph!", completion = "Thank you for leading us to victory. All hail, Highlord {name}!", objectives = "Listen as you are honored by the Order of the Silver Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43698] = { id = 43698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumenstone", description = "To prepare for the battle ahead, we will need armor and weapons.\n\nWe have learned of lumenstone, a rare metal that can negate magic... even fel magic.\n\nIt is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", progress = "Have you acquired any lumenstone?", completion = "There's enough lumenstone here to craft armor and weapons for an army. Thank you, Highlord.", objectives = "Collect 50 Lumenstone by sending champions on \"Lumenstone\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43699] = { id = 43699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of the World", description = "Requests are pouring in from across the Broken Isles for our aid, Highlord.\n\nI know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help.\n\nWe cannot turn our backs on those who need our aid.", completion = "Thank you, Highlord. Too many dangers abound in these dark times. With heroes like you out there, we are all a little bit safer.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43700] = { id = 43700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in the Darkness", description = "Highlord, thank goodness you've arrived! The invasion of Netherlight Temple has begun.\n\nOur forces are already waiting on the other side of the portal.\n\nJoin them, and we will close the trap around Lord Balnazzar.", progress = "The priests have always been our allies and friends. Now, we stand united against a common cause.", completion = "Victory is ours, Highlord.", objectives = "Go to Netherlight Temple using the priest's portal in Dalaran, then defend Netherlight Temple and slay Lord Balnazzar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43701] = { id = 43701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lothraxion", objectives = "I am sure you have many questions, Highlord {name}. It was fate that our paths crossed that day on Niskara.\n\nI serve High Exarch Turalyon and Lady Alleria Windrunner. When the Legion turned its armies toward Azeroth, I was sent here to help protect it.\n\nHow I got to Niskara is a tale for another time, but had it not been for you, I would still be Balnazzar's prisoner.\n\nNow, I can fulfill my original mission. Let me fight for you. Together, we will drive back the Burning Legion!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43702] = { id = 43702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Softening the Target", description = "The Archdruid's end draws near. His memory will live on in the hearts of all who knew him.\n\nElothir's desperate efforts revealed that Malfurion is being held in Shala'nir, amidst the roots of Shaladrassil.\n\nMy love. So near, yet so far....\n\nShala'nir is infested with Nightmare creatures. To rush in would be suicide.\n\nI subdued one of Xavius' creatures. Use it against him, {name} and clear us a path.", progress = "Have you managed to thin their numbers?", completion = "This place remains deadly, but we can now press forward.", objectives = "Slay 50 Nightmare Creatures in Shala'nir riding the Subdued Nightwing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43703] = { id = 43703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 01" }
quests[43704] = { id = 43704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 02" }
quests[43705] = { id = 43705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobundo's Last Stand", description = "The Exodar shook from the force of the Legion's arrival. Before we could react, demons were running rampant through the halls, slaughtering everything in their path. If it were not for the Prophet, we would have all perished in the initial assault.\n\nI was charged with evacuating the Crystal Hall, which is when my Broken and I were separated from the main force.\n\nWe fell back into the collapsed hall to make our last stand.\n\nWith your aid, we may survive this invasion.", progress = "The Legion must fall!", completion = "You have my thanks, and the gratitude of the Broken, hero. Many would have considered us an acceptable loss, yet you have shown us great compassion and kindness. An act that I - we - will not soon forget.\n\nNow we will return to the Vault of Lights and assist Velen as best we can.", objectives = "Defend Farseer Nobundo from the Legion Assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43706] = { id = 43706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hub Mana Tree Tracking - Stage 03" }
