quests[43723] = { id = 43723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Taoshi", objectives = "I am honored beyond words, {name}. I will gladly serve as your champion.\n\nPoint me in the right direction. I can sneak anywhere. Find out anything.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43724] = { id = 43724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Master Mathias Shaw", objectives = "Shall we form an alliance, you and I? Of course, I dare not officially become one of the Uncrowned, let alone the Council of Shadows.\n\nI am the leader of SI:7 after all.\n\nBut, when you need my assistance or guidance, you need but ask. I will be there. We will work together through back channels to ensure that the Burning Legion is destroyed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
