quests[43748] = { id = 43748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Currency Treasure - Felsoul Hold" }
quests[43749] = { id = 43749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "<Sir/Mam>, my head would be in a book whether I was supported by the Tirisgarde or not... but my means are limited. Learning more about this weapon of yours is critical to the fight against the Legion, I know it.\n\nIf you want more researchers on the job to turn out results faster, we'll need to supply the resources to keep them going.\n\nI promise you it will be worth every minute.", progress = "There's such a wealth of knowledge in these books.  I wish there were more of me to pour through them all at once.", completion = "You are lovely. Just lovely. I'll get to work right away.\n\nKeep us in mind with any resources the Tirisgarde can spare. If you can keep the researchers busy, we should unfold everything there is to know about your weapon in no time.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43750] = { id = 43750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Battle", description = "Once, the mighty titanforged keepers of Ulduar and Odyn acted as one. Ever since Odyn broke off to create the valarjar, not even Odyn's own son Thorim is bound to follow his father's advice.\n\nThere is one hope to unite the forces of Skyhold and Ulduar however.\n\nThe Gjallarhorn was a gift given to Hymdall before Odyn's departure. The keepers of Ulduar are oathbound to answer the call of the Gjallarhorn were it to be sounded as it would signal that the end times are upon us!", completion = "Ah yes, the Gjallarhorn.", objectives = "Speak to Hymdall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
