quests[43785] = { id = 43785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Arator the Redeemer", objectives = "Highlord {name}, for many years I sought to follow the footsteps of my father, Turalyon.\n\nIn you, I see an exemplary leader, one who can still teach me so much. In you, I see a champion rivaling my father himself.\n\nI would gladly lay down my life and fight for the Order of the Silver Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
