quests[43797] = { id = 43797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Conclave", description = "The priests of the Conclave are formidable allies. With our combined strength, we may just have a chance to slay the dreadlord, forever.\n\nLet Alonsus Faol know that we will be by your side and ready to fight when you need us.", completion = "With the paladins on our side, united under the Light, the prophecy is fulfilled.\n\nWe must now prepare. Balnazzar will attack, and we need to be ready.", objectives = "Return to Alonsus Faol within Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
