quests[43805] = { id = 43805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquatic Assassination" }
quests[43806] = { id = 43806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Broken Shore", description = "The third fleet has shipped out ahead of us, {name}. This gryphon will bring you to them.\n\nGood luck out there. It's clear the Legion isn't going to make this easy, but let's hope King Varian has matters well in hand.", completion = "Ah, {name}, you're up! I'm relieved you made it out of that bloodbath alive. We lost so many good women and men down there...\n\n\n\nDamn the Horde for serving us up to the Legion!", objectives = "Rendezvous with the third fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
