quests[43808] = { id = 43808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moon Guard Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43809] = { id = 43809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tel'anor'eporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43810] = { id = 43810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to Business", description = "First things first, {name}: we must set up our camp.\n\nWe do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike.\n\nThey are drawing up their battle lines within the city, but could attack us while we are setting up our defenses.\n\nVenture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.", completion = "Any regret I had for these people vanished when they went under that shield.", objectives = "Enter the Grand Promenade and slay 15 defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43811] = { id = 43811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunastre Estate Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43812] = { id = 43812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to Business", description = "Time to get to business, {name}. We cannot afford to tarry.\n\nWhile we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes.\n\nThey are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.", completion = "Excellent. We will be able to defend our borders for now.", objectives = "Enter the Grand Promenade and slay 15 defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43813] = { id = 43813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum of Order Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43814] = { id = 43814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unspeakable Collaborators" }
quests[43815] = { id = 43815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karthax" }
quests[43816] = { id = 43816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "I will need more research material if I'm to keep improving on our current records.\n\nIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.", objectives = "Use Illiana Dreadmoore's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43817] = { id = 43817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "It may sound strange, but in order to do more research I will need, uh, more research material.\n\nIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.", objectives = "Use Vehu's notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43818] = { id = 43818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "I will need to increase our overall knowledge levels before I can research the artifact further.\n\nBefore I can get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.", objectives = "Use Celadine's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43819] = { id = 43819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "You have a weapon both ancient and powerful. And yet, we barely understand it.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. I can help with that.\n\nBefore I can get started though, I need a series of ancient tomes. They may be hard to procure. I asked one of the scouts to seek them out, here are her notes.", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Holt needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43820] = { id = 43820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "We definitely have plans to improve our research methods. \n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I had one of the initiates attempt to find them. Here are her notes.", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Lorewalker Cho needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43821] = { id = 43821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "I have some ideas on how we can improve our research methods.\n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I put one of the researchers on digging up where they might be. Here are her notes.", objectives = "Use Sister Elda's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43822] = { id = 43822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "More research? Absolutely!\n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.", objectives = "Use Juvess' notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43823] = { id = 43823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "I think I can help you, I mean all of us, out.\n\nBefore I can get started though, I need some books. Some important ones. They may be hard to pinch. I'll give you my notes to help you find them.", objectives = "Use Fillius' notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43824] = { id = 43824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "I know of a few books that will give me the right place to start. They may be hard to get your hands on, but they'll be worth it. I'll give you my notes to help you find them.", objectives = "Use Gorma's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43825] = { id = 43825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "Before I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.", objectives = "Use Mile's notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43826] = { id = 43826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden History", description = "You wield ancient steel, strengthened by magics we barely understand.\n\nIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they've fought in. I can help with this.\n\nYour races use books to store their histories, and I will need some of these to piece together the legend of your steel. I asked one of your followers to look into their locations for me. Here are her notes.", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Fjornson needs to begin research on your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43827] = { id = 43827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwing the Portals" }
quests[43828] = { id = 43828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheep Summon Daily Roll" }
quests[43829] = { id = 43829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy vs. Spy", description = "SI:7 is the espionage and intel branch of the Alliance. They are based out of Stormwind City and headed up by Master Mathias Shaw. As of late, they have been acting, shall we say, peculiar.\n\nI would like for you to send some of our people out to assess the situation. It might be nothing, but I am not fond of situations that I do not fully understand.\n\nIf we are going to win this war against the Burning Legion, the last thing we need is for something wholly unexpected to occur.", completion = "Why is Mathias Shaw stepping up the number of agents that he has in Horde territory?\n\nWe must keep a close and watchful eye on this situation.", objectives = "Use the Scouting Map and complete the mission, \"Spy vs. Spy\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43830] = { id = 43830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 001 - South of Felsoul" }
quests[43831] = { id = 43831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 002 - Felsoul Upper" }
quests[43832] = { id = 43832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixirs of Aid", description = "We can never be too prepared for battle. The Legion will strike at any moment, and we must be ready to deal with a multitude of injuries and afflictions.\n\nZabra and Yalia have provided me a list of their most potent potions and battle elixirs than can do everything from restore health to blind the enemy.\n\nWe have an exhaustive list of ingredients that we'll need in order to craft a respectable supply.", completion = "You are as dependable as you are resourceful.", objectives = "Collect elixir crafting ingredients for Alonsus Faol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
