quests[43840] = { id = 43840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 008 - Collapse Depths" }
quests[43841] = { id = 43841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convincin' Old Yancey", description = "Avast ye! Th' time be long overdue that we get some more pirate blood into our ranks.\n\n<Crackers gives a sudden squawk in agreement.>\n\nAnd I know just th' man t' do it.\n\nI'm talkin' about good old Yancey Grillsen, o' course. He's an old salt down Stranglethorn way.\n\nSend some o' your land lovin' scallywags off t' round him up.", completion = "Arrr! Now that be what I like t' hear.\n\nWhat do you think, Crackers... will a bunch o' freebooters class up this crow's nest or scuttle th' ship? I say it's a fair toss o' th' bones.", objectives = "Use the Scouting Map and complete the mission, \"Convincin' Old Yancey\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
