quests[43851] = { id = 43851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting More Troops", description = "Word of your leadership has spread rather fast. Priests of all sorts have traveled to the temple to lend their aid.\n\nWe're lucky enough to have caught the eye of Vicar Eliza. She's quite the leader in her own right, commanding countless devotees that do her bidding without question. \n\nSpeak to her now.", completion = "It is an honor to serve you, High {class}.", objectives = "Speak to Vicar Eliza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43852] = { id = 43852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fancy Lads and Buccaneers", description = "Aye, it warms me heart t' know that Yancey's now part o' th' crew.\n\n<Tethys feeds Crackers some cackle fruit from the table.>\n\nWhy don't you be a good <lad/lass> and see if he can sponge us up some bilge rats.", progress = "Are you lookin' t' be shark bait? Where be our new crew of pirates?\n\n<Crackers squawks in agreement.>", completion = "Now that's more like it. Get them some holystone and put them t' work scrubbin' th' deck.\n\nThat and a few black jacks o' rum will put courage in their sails.", objectives = "Speak with your Pirate recruiter, Yancey Grillsen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
