quests[43876] = { id = 43876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 041 - City - Noble Docks" }
quests[43877] = { id = 43877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "Any death knight worth their salt knows the weapon they wield as if they were born with it.  But you now carry a weapon older than any in this hall.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43878] = { id = 43878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "A demon hunter is nothing without blades with which to cut flesh. Yet those you wield are older than even you... and have power we don't understand yet.\n\nIf you truly want to unlock all of their potential, we need to learn more about them. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43879] = { id = 43879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That's where I come in. It's my specialty.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43880] = { id = 43880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can help with that.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43881] = { id = 43881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I am quite good at such things.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43882] = { id = 43882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nighthold: Vaults", description = "The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?", objectives = "Kill Trilliax in The Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43883] = { id = 43883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a mighty weapon with a long history, one we barely understand. If we truly want to unlock all of its potential, we need to learn more about it. I can get workin' on that for ya.\n\nStill, it'll take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43884] = { id = 43884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can do this for you.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Excellent. I'll get back to you with the results as soon as I can.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43885] = { id = 43885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "Your weapons are undeniably powerful, but we know near nothing about'm.\n\nIf we want to unlock all of their potential, we need to dig up some dirt on how they work, what they've done... get to know them, ya know? That's where I come in. I dig up dirt all the time. I mean, not literally, but... you know what I mean.\n\nIt will take time and more eyes than just mine to sift through all this. We should prioritize some of the order's resources towards this research. It will be worth every minute.", progress = "I like books.", completion = "On it, boss. Will get back to you soon!", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43886] = { id = 43886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking to the Wind", description = "You have a weapon both ancient and powerful. We know stories of it, but little about its origins.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. The winds can help us with this, but we need to know what to ask.\n\nIt will take more shaman than just myself to learn everything there is to know about this artifact of yours. We should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Thank you. I'll get back to you with what I've learned soon.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43887] = { id = 43887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That is a thing that I can do for you.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", completion = "Very good. I'll get back to you with the results soon.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43888] = { id = 43888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Books", description = "You wield ancient steel, strengthened by magics we barely understand.\n\nIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they've fought in. I can help with this.\n\nAny resources that you can prioritize towards this research will be well worth it.", completion = "I will have results for you soon.", objectives = "Start a Research Work Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43889] = { id = 43889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nighthold: Vaults", description = "The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?", objectives = "Kill Trilliax in The Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43890] = { id = 43890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nighthold: Vaults", description = "The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?", objectives = "Kill Trilliax in The Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43891] = { id = 43891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nighthold: Vaults", description = "The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?", objectives = "Kill Trilliax in The Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43892] = { id = 43892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Order Resources", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end?  Will you ever stop risking others lives just to satisfy your greedy nature?\n\nYou can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
quests[43893] = { id = 43893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Stashed Order Resources", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
quests[43894] = { id = 43894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Extraneous Order Resources", progress = "Four times the cost of the first for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
quests[43895] = { id = 43895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Gold", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold?  That is the offer I present.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[43896] = { id = 43896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Piles of Gold", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[43897] = { id = 43897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Immense Fortune of Gold", progress = "Four times the cost of the first, but for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
quests[43898] = { id = 43898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing to Move", description = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion.\n\nThe final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself.\n\nBefore we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.", completion = "We've found a back entrance into the Nighthold that should provide some relief from the armies at the main gate.\n\n'Some' being key.", objectives = "Meet Archmage Kalec in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43899] = { id = 43899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steeds of the Damned", description = "Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen.\n\nSalanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items.\n\nUse the mission table to assign your chosen champions to the task.", completion = "Excellent work, Deathlord. The missions for the Steeds of the Damned were successful. Salanar the Horseman now has the first set of necessary components for conjuring the steeds.", objectives = "Complete 5 \"Fallen Steeds\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43900] = { id = 43900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: All - Troop A Enabled" }
quests[43901] = { id = 43901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: All - Troop B Enabled" }
quests[43902] = { id = 43902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Fall of Cenarius", description = "While we know that the Nightmare bends the boundary between reality and dream, there is no doubt of the threat upon us. Our own allies have fallen into darkness.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?", objectives = "Defeat Cenarius in the Emerald Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43903] = { id = 43903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Xavius", description = "The time has come to tackle the source of the Nightmare, and restore balance to the Emerald Dream. Battle into the heart of the Nightmare, and face the Nightmare Lord Xavius.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?", objectives = "Defeat Xavius in the Emerald Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
